-- 61_zone_split.sql — map 751 Lordaeron extension, step 1 of the DB layer.
--
-- Splits the legacy single zone 4924 across the 8 real zones now stamped into
-- the retagged terrain.  Zone per spawn is resolved from the ADT the spawn
-- stands on: uniform tiles by tile, mixed tiles by 33.33y MCNK chunk.
--
-- PREREQUISITE: the retagged ADTs and the 7 new AreaTable rows (4932/4933/
-- 4935-4939) must be deployed, and Map.dbc AreaTableID for 751 flipped 4924->0,
-- in the SAME deploy.  Running this against the old single-zone terrain is
-- harmless but pointless — the server would still report 4924 everywhere.
--
-- Idempotent: re-running recomputes from the same lookup tables.

DROP TABLE IF EXISTS `dc_map751_tilezone`;
CREATE TABLE `dc_map751_tilezone` (
  `col` TINYINT UNSIGNED NOT NULL,
  `row` TINYINT UNSIGNED NOT NULL,
  `zone` SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (`col`,`row`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `dc_map751_chunkzone`;
CREATE TABLE `dc_map751_chunkzone` (
  `col` TINYINT UNSIGNED NOT NULL,
  `row` TINYINT UNSIGNED NOT NULL,
  `xsub` TINYINT UNSIGNED NOT NULL,
  `ysub` TINYINT UNSIGNED NOT NULL,
  `zone` SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (`col`,`row`,`xsub`,`ysub`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

