  `areaId` SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (`kind`,`guid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO `dc_map751_zone_backup` (`kind`,`guid`,`zoneId`,`areaId`)
  SELECT 'c',`guid`,`zoneId`,`areaId` FROM `creature`   WHERE `map`=751;
INSERT IGNORE INTO `dc_map751_zone_backup` (`kind`,`guid`,`zoneId`,`areaId`)
  SELECT 'g',`guid`,`zoneId`,`areaId` FROM `gameobject` WHERE `map`=751;

-- ---------------------------------------------------------------------------
-- Apply: mixed tiles first (chunk precision), then uniform tiles.
-- ---------------------------------------------------------------------------
UPDATE `creature` t
  JOIN `dc_map751_chunkzone` z
    ON z.`col`  = FLOOR(32 - t.`position_y`/533.3333333)
   AND z.`row`  = FLOOR(32 - t.`position_x`/533.3333333)
   AND z.`xsub` = FLOOR((32 - t.`position_x`/533.3333333 - z.`row`)*16)
   AND z.`ysub` = FLOOR((32 - t.`position_y`/533.3333333 - z.`col`)*16)
  SET t.`zoneId` = z.`zone`, t.`areaId` = z.`zone`
  WHERE t.`map` = 751;

UPDATE `creature` t
  JOIN `dc_map751_tilezone` z
    ON z.`col` = FLOOR(32 - t.`position_y`/533.3333333)
   AND z.`row` = FLOOR(32 - t.`position_x`/533.3333333)
  SET t.`zoneId` = z.`zone`, t.`areaId` = z.`zone`
  WHERE t.`map` = 751;

UPDATE `gameobject` t
  JOIN `dc_map751_chunkzone` z
    ON z.`col`  = FLOOR(32 - t.`position_y`/533.3333333)
   AND z.`row`  = FLOOR(32 - t.`position_x`/533.3333333)
   AND z.`xsub` = FLOOR((32 - t.`position_x`/533.3333333 - z.`row`)*16)
   AND z.`ysub` = FLOOR((32 - t.`position_y`/533.3333333 - z.`col`)*16)
  SET t.`zoneId` = z.`zone`, t.`areaId` = z.`zone`
  WHERE t.`map` = 751;

UPDATE `gameobject` t
  JOIN `dc_map751_tilezone` z
    ON z.`col` = FLOOR(32 - t.`position_y`/533.3333333)
   AND z.`row` = FLOOR(32 - t.`position_x`/533.3333333)
  SET t.`zoneId` = z.`zone`, t.`areaId` = z.`zone`
  WHERE t.`map` = 751;

-- ---------------------------------------------------------------------------
-- Verify. Expect zero rows left on 4924 that are not genuinely in EPL, and no
-- spawn outside the 186 staged tiles (those would be off-map leftovers).
-- ---------------------------------------------------------------------------
SELECT `zoneId`, COUNT(*) AS spawns FROM `creature`   WHERE `map`=751 GROUP BY `zoneId` ORDER BY spawns DESC;
SELECT `zoneId`, COUNT(*) AS objects FROM `gameobject` WHERE `map`=751 GROUP BY `zoneId` ORDER BY objects DESC;
SELECT 'creature off-map' AS what, COUNT(*) AS n FROM `creature` t
  LEFT JOIN `dc_map751_tilezone` u ON u.`col`=FLOOR(32-t.`position_y`/533.3333333) AND u.`row`=FLOOR(32-t.`position_x`/533.3333333)
  LEFT JOIN `dc_map751_chunkzone` m ON m.`col`=FLOOR(32-t.`position_y`/533.3333333) AND m.`row`=FLOOR(32-t.`position_x`/533.3333333)
  WHERE t.`map`=751 AND u.`zone` IS NULL AND m.`zone` IS NULL
UNION ALL
SELECT 'gameobject off-map', COUNT(*) FROM `gameobject` t
  LEFT JOIN `dc_map751_tilezone` u ON u.`col`=FLOOR(32-t.`position_y`/533.3333333) AND u.`row`=FLOOR(32-t.`position_x`/533.3333333)
  LEFT JOIN `dc_map751_chunkzone` m ON m.`col`=FLOOR(32-t.`position_y`/533.3333333) AND m.`row`=FLOOR(32-t.`position_x`/533.3333333)
  WHERE t.`map`=751 AND u.`zone` IS NULL AND m.`zone` IS NULL;
